            value = type.value;
            break;
          case BYTE:
            value = byte.class.getName();
            break;
          case CHAR:
            value = char.class.getName();
            break;
          case DOUBLE:
            value = double.class.getName();
            break;
          case FLOAT:
            value = float.class.getName();
            break;
          case INT:
            value = int.class.getName();
            break;
          case LONG:
            value = long.class.getName();
            break;
          case SHORT:
