   577	  static final class ReferenceAwareSyntheticRetention {
   578	    private final Set<MemberKey> candidates = new HashSet<>();
   579	    private final Set<MemberKey> retained = new HashSet<>();
   580	    private final Set<ClassNode> processedClasses = Collections.newSetFromMap(new IdentityHashMap<>());
   581	
   582	    boolean markClassProcessed(ClassNode node) {
   583	      return processedClasses.add(node);
   584	    }
   585	
   586	    void preparePass(ClassNode root) {
   587	      resetAnnotationState(root);
   588	    }
   589	
   590	    boolean shouldHide(MemberKey member) {
   591	      candidates.add(member);
