   593	    }
   594	
   595	    boolean retainReferences(TextBuffer buffer) {
   596	      boolean changed = false;
   597	
   598	      for (TextToken token : buffer.getTokens()) {
   599	        if (token.isDeclaration()) {
   600	          continue;
   601	        }
   602	
   603	        MemberKey referenced = null;
   604	        if (token instanceof FieldTextToken field) {
   605	          referenced = MemberKey.field(field.className, field.name, field.descriptor.descriptorString);
   606	        }
   607	        else if (token instanceof MethodTextToken method) {
   608	          referenced = MemberKey.method(method.className, method.name, method.descriptor.toString());
   609	        }
   610	        else if (token instanceof ClassTextToken clazz) {
   611	          referenced = MemberKey.memberClass(clazz.qualifiedName);
   612	        }
   613	
   614	        if (referenced != null) {
   615	          MemberKey candidate = findCandidate(referenced);
   616	          if (candidate != null) {
   617	            changed |= retained.add(candidate);
   618	          }
   619	        }
   620	      }
   621	
   622	      return changed;
   623	    }
   624	
   625	    private MemberKey findCandidate(MemberKey referenced) {
   626	      if (candidates.contains(referenced)) {
   627	        return referenced;
   628	      }
   629	      if (referenced.kind == MemberKind.MEMBER_CLASS) {
   630	        return null;
   631	      }
   632	
   633	      MemberKey declaration = findDeclaration(referenced, referenced.owner, new HashSet<>());
   634	      return candidates.contains(declaration) ? declaration : null;
