   650	      if (declared) {
   651	        return new MemberKey(referenced.kind, clazz.qualifiedName, referenced.name, referenced.descriptor);
   652	      }
   653	
   654	      if (referenced.kind == MemberKind.FIELD) {
   655	        for (String interfaceName : clazz.getInterfaceNames()) {
   656	          MemberKey declaration = findDeclaration(referenced, interfaceName, visited);
   657	          if (declaration != null) {
   658	            return declaration;
   659	          }
   660	        }
   661	      }
   662	
   663	      MemberKey declaration = findDeclaration(referenced, clazz.superClass == null ? null : clazz.superClass.getString(), visited);
